const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const fontBytes = fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf');
  const font = await doc.embedFont(fontBytes);

  const W = 595, H = 842;
  const ML = 50, MR = 50, MT = 780;
  const page = doc.addPage([W, H]);

  const title = 'AI 助手能力总结';
  page.drawText(title, { x: ML, y: MT, size: 26, font });

  const subtitle = '以下是我可以为您完成的主要工作类别与典型场景';
  page.drawText(subtitle, { x: ML, y: MT - 36, size: 12, font });

  // 分隔线
  page.drawLine({ start: { x: ML, y: MT - 50 }, end: { x: W - MR, y: MT - 50 }, thickness: 1, color: [0.2, 0.2, 0.2] });

  const sections = [
    {
      head: '1. 文档与办公文件',
      lines: [
        '• 创建 Word、Excel、PowerPoint、PDF 等办公文档',
        '• 读取并理解上传的 PDF/Office/CSV 原件内容',
        '• 对已有 Office 文件做有限的文本替换与编辑',
      ]
    },
    {
      head: '2. 数据分析与可视化',
      lines: [
        '• 分析 CSV / XLSX / JSON 数据，给出可复现的计算结论',
        '• 生成静态图表（柱状图、折线图、饼图等），校验标签与单位',
      ]
    },
    {
      head: '3. 会议与沟通',
      lines: [
        '• 将会议转录整理为纪要：决策、行动项与证据位置',
        '• 准备会议背景材料、议程与预读文档',
        '• 撰写内部公告、领导更新、FAQ、周报等沟通稿',
      ]
    },
    {
      head: '4. 研究与知识问答',
      lines: [
        '• 联网检索公开资料，形成带引用的研究报告',
        '• 基于组织内部资料回答政策/项目问题，标注出处',
        '• 综合多场访谈记录，提炼主题、引文与反例',
      ]
    },
    {
      head: '5. 用户研究',
      lines: [
        '• 制定研究计划、招募条件与中立访谈提纲',
        '• 将需求讨论提炼为 MAAU 画布（最小智能体可执行单元）',
      ]
    },
    {
      head: '6. 多媒体与创意',
      lines: [
        '• 音频转文字，保留时间范围与识别局限说明',
        '• 为海报/配图确定构图与文案，生成或排版视觉作品',
        '• 创建交互式网页产物（Web Artifact）',
      ]
    },
    {
      head: '7. 项目管理与报告',
      lines: [
        '• 依据项目状态生成周报、里程碑或领导简报',
        '• 绘制/修改 Mermaid 流程图与画布 Markdown',
      ]
    },
    {
      head: '8. 技能扩展',
      lines: [
        '• 将重复性工作流整理为可导入的技能草稿包',
      ]
    },
  ];

  let y = MT - 78;
  const headSize = 14;
  const bodySize = 11;
  const lineH = 18;
  const sectionGap = 10;

  for (const sec of sections) {
    page.drawText(sec.head, { x: ML, y, size: headSize, font });
    y -= lineH + 4;
    for (const ln of sec.lines) {
      page.drawText(ln, { x: ML + 10, y, size: bodySize, font });
      y -= lineH;
    }
    y -= sectionGap;
  }

  // 底部备注
  const noteY = 42;
  page.drawText('注：以上能力取决于当前已授权的技能与可用资源；具体任务请以实际对话为准。', {
    x: ML, y: noteY, size: 9, font, color: [0.4, 0.4, 0.4]
  });

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/capabilities-summary.pdf', bytes);
  console.log('PDF written to /workspace/capabilities-summary.pdf');
})().catch(e => { console.error(e.stack); process.exit(1); });
